package com.labmaker.app;
import org.junit.Test;import static org.junit.Assert.*;import okhttp3.*;import okhttp3.mockwebserver.*;import org.json.*;import java.io.*;import java.util.concurrent.TimeUnit;
public class FeedbackUploadTest {
 final String id="12345678-1234-1234-1234-123456789abc",object="contributions/feedbacks/abcdefab-1234-1234-1234-123456789abc/feedback.json";
 OkHttpClient client(){return new OkHttpClient.Builder().followRedirects(false).followSslRedirects(false).retryOnConnectionFailure(false).callTimeout(2,TimeUnit.SECONDS).build();}
 JSONObject payload()throws Exception{return FeedbackUpload.payload("测试反馈内容", "直螺线管磁场分布的测量","0.33.0",id);}
 JSONObject credentials(MockWebServer server,JSONObject payload)throws Exception{int size=payload.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length;return new JSONObject().put("ok",true).put("items",new JSONArray().put(new JSONObject().put("key","contributions/feedbacks/"+id+"/feedback.json").put("objectKey",object).put("size",size).put("putUrl",server.url("/"+object+"?signed=example").toString())));}
 @Test public void sendsOnlyReviewedFieldsAndBoundedSinglePut()throws Exception {try(MockWebServer server=new MockWebServer()){server.start();JSONObject payload=payload();server.enqueue(new MockResponse().setBody(credentials(server,payload).toString()));server.enqueue(new MockResponse().setResponseCode(200));FeedbackUpload f=new FeedbackUpload(client(),server.url("/credentials"),server.url("/"));assertEquals("sent",f.submit(payload,new FeedbackUpload.Work()).getString("state"));RecordedRequest first=server.takeRequest(),second=server.takeRequest();assertEquals("POST",first.getMethod());assertEquals("PUT",second.getMethod());assertEquals("true",second.getHeader("x-cos-forbid-overwrite"));assertEquals("application/octet-stream",second.getHeader("Content-Type"));assertNull(first.getHeader("Cookie"));assertNull(second.getHeader("Authorization"));JSONObject body=new JSONObject(second.getBody().readUtf8());assertEquals(6,body.length());assertEquals("feedback",body.getString("kind"));assertEquals("android",body.getString("platform"));assertFalse(body.has("studentId"));assertEquals(2,server.getRequestCount());}}
 @Test public void validatesBodyAndNeverIncludesUnrequestedLocalData()throws Exception {for(String text:new String[]{"短", "x".repeat(5001)})try{FeedbackUpload.payload(text,"","0.33.0",id);fail();}catch(IOException expected){}try{FeedbackUpload.payload("反馈测试内容","a/b","0.33.0",id);fail();}catch(IOException expected){}assertEquals("反馈测试内容",FeedbackUpload.payload(" 反馈测试内容 ","","0.33.0",id).getString("text"));}
 @Test public void rejectsUnboundTicketVariants()throws Exception {try(MockWebServer server=new MockWebServer()){server.start();JSONObject p=payload();FeedbackUpload f=new FeedbackUpload(client(),server.url("/credentials"),server.url("/"));String key="contributions/feedbacks/"+id+"/feedback.json";int size=p.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length;for(String field:new String[]{"key","size","objectKey","putUrl"}){JSONObject raw=credentials(server,p),item=raw.getJSONArray("items").getJSONObject(0);if(field.equals("size"))item.put(field,size+1);else item.put(field,field.equals("putUrl")?"https://example.com/"+object+"?signed=x":"bad");try{f.ticket(raw,key,size);fail(field);}catch(IOException expected){}}for(String url:new String[]{server.url("/other?x=1").toString(),server.url("/"+object).toString(),server.url("/"+object+"?x=1#bad").toString()}){JSONObject raw=credentials(server,p);raw.getJSONArray("items").getJSONObject(0).put("putUrl",url);try{f.ticket(raw,key,size);fail();}catch(IOException expected){}}}}
 @Test public void credentialsRedirectIsNotFollowedAndNoPutIsSent()throws Exception {try(MockWebServer server=new MockWebServer()){server.start();server.enqueue(new MockResponse().setResponseCode(302).setHeader("Location",server.url("/unexpected")));FeedbackUpload f=new FeedbackUpload(client(),server.url("/credentials"),server.url("/"));try{f.submit(payload(),new FeedbackUpload.Work());fail();}catch(IOException expected){}assertEquals(1,server.getRequestCount());}}
 @Test public void credentialFailureAndMalformedBodyNeverPut()throws Exception {for(String body:new String[]{"not JSON", "{}", "x".repeat(32769)})try(MockWebServer server=new MockWebServer()){server.start();server.enqueue(new MockResponse().setBody(body));FeedbackUpload f=new FeedbackUpload(client(),server.url("/credentials"),server.url("/"));try{f.submit(payload(),new FeedbackUpload.Work());fail();}catch(IOException expected){}assertEquals(1,server.getRequestCount());}}
 @Test public void ambiguousPutIsNotRetried()throws Exception {try(MockWebServer server=new MockWebServer()){server.start();JSONObject p=payload();server.enqueue(new MockResponse().setBody(credentials(server,p).toString()));server.enqueue(new MockResponse().setSocketPolicy(SocketPolicy.DISCONNECT_AFTER_REQUEST));FeedbackUpload f=new FeedbackUpload(client(),server.url("/credentials"),server.url("/"));assertEquals("unknown",f.submit(p,new FeedbackUpload.Work()).getString("state"));assertEquals(2,server.getRequestCount());}}
 @Test public void cancellationBeforeCredentialsSendsNothing()throws Exception {try(MockWebServer server=new MockWebServer()){server.start();FeedbackUpload.Work work=new FeedbackUpload.Work();work.cancel();FeedbackUpload f=new FeedbackUpload(client(),server.url("/credentials"),server.url("/"));assertEquals("cancelled",f.submit(payload(),work).getString("state"));assertEquals(0,server.getRequestCount());}}
 @Test public void putFailureDoesNotBecomeSuccessOrRetry()throws Exception {try(MockWebServer server=new MockWebServer()){server.start();JSONObject p=payload();server.enqueue(new MockResponse().setBody(credentials(server,p).toString()));server.enqueue(new MockResponse().setResponseCode(409));FeedbackUpload f=new FeedbackUpload(client(),server.url("/credentials"),server.url("/"));assertEquals("unknown",f.submit(p,new FeedbackUpload.Work()).getString("state"));assertEquals(2,server.getRequestCount());}}
 @Test public void cancellationAfterCredentialsPreventsPut()throws Exception {try(MockWebServer server=new MockWebServer()){server.start();JSONObject p=payload();FeedbackUpload.Work work=new FeedbackUpload.Work();server.setDispatcher(new okhttp3.mockwebserver.Dispatcher(){@Override public MockResponse dispatch(RecordedRequest request){try{work.cancel();return new MockResponse().setBody(credentials(server,p).toString());}catch(Exception e){return new MockResponse().setResponseCode(500);}}});FeedbackUpload f=new FeedbackUpload(client(),server.url("/credentials"),server.url("/"));assertEquals("cancelled",f.submit(p,work).getString("state"));assertEquals(1,server.getRequestCount());}}
}
